func TestPasswordBetterAuthCompatibility(t *testing.T) {
	// Exact hashes generated by Node's @better-auth/utils/password (v0.4.2).
	const (
		nodeHashASCII = "d416ca3032f5c5db8d1478f3d6e58092:2b39dbfebe0b301482a051c8af789d46bb039dd4f6384999f81625a2f45ff292876c27b1a1d3fd07c248bc5596c67e7a30ba1fec2360541b6f76a397c48c764f"
		nodeHashNFKC  = "a06abd3b0371b8b194b13c97c4e10cdd:181301a3c5873301803c167acb7bf11fbf80373e815891aa5e2cfbb4dcdc6e6864ad9e2e6521e352c6bc9af27c79b5436761a3c172b3a93265f2fda3ffcf31a4"
	)

	ok, err := auth.VerifyPassword(nodeHashASCII, "correct-horse-battery-staple")
	if err != nil || !ok {
		t.Fatalf("VerifyPassword(nodeHashASCII) = (%v, %v), want (true, nil)", ok, err)
	}
	ok, err = auth.VerifyPassword(nodeHashASCII, "wrong-password")
	if err != nil || ok {
		t.Fatalf("VerifyPassword(wrong) = (%v, %v), want (false, nil)", ok, err)
	}
	// Verify NFKC normalization matches Node's password.normalize("NFKC").
	ok, err = auth.VerifyPassword(nodeHashNFKC, "café\u0301-NFKC-test")
	if err != nil || !ok {
		t.Fatalf("VerifyPassword(nodeHashNFKC) = (%v, %v), want (true, nil)", ok, err)
	}

	// Verify Go-generated hash format and round-trip.
	hashed, err := auth.HashPassword("my-secret-passphrase")
	if err != nil {
		t.Fatalf("HashPassword: %v", err)
	}
	if len(hashed) != 161 {
		t.Fatalf("len(hashed) = %d, want 161", len(hashed))
	}
	parts := strings.Split(hashed, ":")
	if len(parts) != 2 || len(parts[0]) != 32 || len(parts[1]) != 128 {
		t.Fatalf("unexpected hash format: %q", hashed)
	}
	ok, err = auth.VerifyPassword(hashed, "my-secret-passphrase")
	if err != nil || !ok {
		t.Fatalf("round-trip VerifyPassword = (%v, %v), want (true, nil)", ok, err)
	}
}

func TestCookieBetterAuthCompatibility(t *testing.T) {
	const (
		token       = "AbCdEfGhIjKlMnOpQrStUvWxYz012345"
		secret      = "test-secret-0123456789abcdef0123456789"
		wantSigned  = "AbCdEfGhIjKlMnOpQrStUvWxYz012345.OVpRClpfvN0ee%2Bhx1C4lgPff4CWs%2BvGdrzGaB8xCjPA%3D"
	)

	got := auth.SignCookieValue(token, secret)
	if got != wantSigned {
		t.Fatalf("SignCookieValue = %q, want %q", got, wantSigned)
	}

	verified, ok := auth.VerifySignedCookieValue(wantSigned, secret)
	if !ok || verified != token {
		t.Fatalf("VerifySignedCookieValue = (%q, %v), want (%q, true)", verified, ok, token)
	}

	if _, ok := auth.VerifySignedCookieValue(wantSigned, "wrong-secret"); ok {
		t.Fatalf("expected invalid signature with wrong secret")
	}
	if _, ok := auth.VerifySignedCookieValue("tampered"+wantSigned, secret); ok {
		t.Fatalf("expected invalid signature for tampered token")
	}
}

func TestCSRFValidation(t *testing.T) {
	const baseURL = "http://127.0.0.1:3000"
	trusted := []string{"https://*.delb.example"}

	// GET passes without Origin.
	req := httptest.NewRequest(http.MethodGet, baseURL+"/api/auth/get-session", nil)
	if err := auth.ValidateCSRF(req, baseURL, trusted); err != nil {
		t.Fatalf("GET should pass CSRF: %v", err)
	}

	// POST with cookie and missing Origin fails with 403.
	req = httptest.NewRequest(http.MethodPost, baseURL+"/api/auth/sign-out", nil)
	req.Header.Set("Cookie", "delb.session_token=abc")
	if err := auth.ValidateCSRF(req, baseURL, trusted); err == nil || err.Status != http.StatusForbidden {
		t.Fatalf("POST with cookie & missing Origin should fail 403, got %v", err)
	}

	// POST with cookie and trusted baseURL Origin passes.
	req = httptest.NewRequest(http.MethodPost, baseURL+"/api/auth/sign-out", nil)
	req.Header.Set("Cookie", "delb.session_token=abc")
	req.Header.Set("Origin", baseURL)
	if err := auth.ValidateCSRF(req, baseURL, trusted); err != nil {
		t.Fatalf("POST with trusted Origin should pass: %v", err)
	}

	// POST with wildcard trusted origin passes.
	req = httptest.NewRequest(http.MethodPost, baseURL+"/api/auth/sign-out", nil)
	req.Header.Set("Cookie", "delb.session_token=abc")
	req.Header.Set("Origin", "https://books.delb.example")
	if err := auth.ValidateCSRF(req, baseURL, trusted); err != nil {
		t.Fatalf("POST with wildcard trusted Origin should pass: %v", err)
	}

	// POST with untrusted Origin fails.
	req = httptest.NewRequest(http.MethodPost, baseURL+"/api/auth/sign-out", nil)
	req.Header.Set("Cookie", "delb.session_token=abc")
	req.Header.Set("Origin", "https://evil.example")
	if err := auth.ValidateCSRF(req, baseURL, trusted); err == nil || err.Status != http.StatusForbidden {
		t.Fatalf("POST with untrusted Origin should fail 403, got %v", err)
	}
}

type testEnv struct {
	t      *testing.T
	opened *db.OpenResult
	server *httptest.Server
	secret string
}

func newTestEnv(t *testing.T) *testEnv {
	t.Helper()
	ctx := context.Background()
	dbPath := filepath.Join(t.TempDir(), "test.db")
	opened, err := db.Open(ctx, "file:"+dbPath)
	if err != nil {
		t.Fatalf("db.Open: %v", err)
	}
	t.Cleanup(func() { _ = opened.DB.Close() })

	if _, err := db.Migrate(ctx, opened.DB, opened.FilePath, opened.IsMemory, delb.MigrationsFS); err != nil {
		t.Fatalf("db.Migrate: %v", err)
	}

	secret := "test-auth-secret-0123456789abcdef0123456789abcdef"
	var srv *httptest.Server
	mux := http.NewServeMux()
	svc := auth.NewService(auth.ServiceOptions{
		DB:     opened.DB,
		Secret: secret,
		Logger: slog.New(slog.NewTextHandler(io.Discard, nil)),
	})
	svc.RegisterRoutes(mux)
	srv = httptest.NewServer(mux)
	t.Cleanup(srv.Close)

	return &testEnv{t: t, opened: opened, server: srv, secret: secret}
}

func (e *testEnv) doJSON(method, path, cookie string, body any) (int, map[string]any, string) {
	e.t.Helper()
	var bodyReader io.Reader
	if body != nil {
		b, err := json.Marshal(body)
		if err != nil {
			e.t.Fatalf("marshal body: %v", err)
		}
		bodyReader = bytes.NewReader(b)
	}
	req, err := http.NewRequest(method, e.server.URL+path, bodyReader)
	if err != nil {
		e.t.Fatalf("new request: %v", err)
	}
	req.Header.Set("Origin", e.server.URL)
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if cookie != "" {
		req.Header.Set("Cookie", cookie)
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		e.t.Fatalf("do %s %s: %v", method, path, err)
	}
	defer resp.Body.Close()

	raw, _ := io.ReadAll(resp.Body)
	var parsed map[string]any
	_ = json.Unmarshal(raw, &parsed)

	var cookiePairs []string
	for _, c := range resp.Cookies() {
		cookiePairs = append(cookiePairs, c.Name+"="+c.Value)
	}
	return resp.StatusCode, parsed, strings.Join(cookiePairs, "; ")
}

func TestBootstrapOwnerConcurrency(t *testing.T) {
	env := newTestEnv(t)
	ctx := context.Background()

	const workers = 6
	var wg sync.WaitGroup
	statuses := make([]int, workers)
	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func(idx int) {
			defer wg.Done()
			code, _, _ := env.doJSON(http.MethodPost, "/api/auth/sign-up/email", "", map[string]any{
				"name":     "Bootstrap User",
				"email":    "boot-" + string(rune('a'+idx)) + "@example.invalid",
				"password": "super-secret-password-123",
			})
			statuses[idx] = code
		}(i)
	}
	wg.Wait()

	for i, code := range statuses {
		if code != http.StatusOK {
			t.Fatalf("worker %d status = %d, want 200 (all statuses: %v)", i, code, statuses)
		}
	}

	var ownerCount int
	if err := env.opened.DB.QueryRowContext(ctx, `SELECT COUNT(*) FROM users WHERE role = 'owner'`).Scan(&ownerCount); err != nil {
		t.Fatalf("count owners: %v", err)
	}
	if ownerCount != 1 {
		t.Fatalf("owner count = %d, want 1", ownerCount)
	}

	var bootstrapState string
	if err := env.opened.DB.QueryRowContext(ctx, `SELECT value FROM system_state WHERE key = 'owner-bootstrap'`).Scan(&bootstrapState); err != nil {
		t.Fatalf("read owner-bootstrap: %v", err)
	}
	if bootstrapState != "complete" {
		t.Fatalf("owner-bootstrap = %q, want complete", bootstrapState)
	}

	var memberCount int
	if err := env.opened.DB.QueryRowContext(ctx, `SELECT COUNT(*) FROM collection_members`).Scan(&memberCount); err != nil {
		t.Fatalf("count collection_members: %v", err)
	}
	if memberCount != workers {
		t.Fatalf("collection_members count = %d, want %d", memberCount, workers)
	}

	// Lowering owner role must NOT allow a later signup to reclaim owner.
	if _, err := env.opened.DB.ExecContext(ctx, `UPDATE users SET role = 'user' WHERE role = 'owner'`); err != nil {
		t.Fatalf("demote owner in test: %v", err)
	}
	code, _, _ := env.doJSON(http.MethodPost, "/api/auth/sign-up/email", "", map[string]any{
		"name":     "Late User",
		"email":    "late@example.invalid",
		"password": "super-secret-password-123",
	})
	if code != http.StatusOK {
		t.Fatalf("late signup status = %d, want 200", code)
	}
	if err := env.opened.DB.QueryRowContext(ctx, `SELECT COUNT(*) FROM users WHERE role = 'owner'`).Scan(&ownerCount); err != nil {
		t.Fatalf("re-count owners: %v", err)
	}
	if ownerCount != 0 {
		t.Fatalf("late signup must not become owner; ownerCount = %d", ownerCount)
	}
}

func TestAuthEndpointsFullLifecycleAndRBAC(t *testing.T) {
	env := newTestEnv(t)
	ctx := context.Background()

	// 1. Initial user-count == 0
	resp, err := http.Get(env.server.URL + "/api/auth/user-count")
	if err != nil {
		t.Fatalf("user-count: %v", err)
	}
	var userCount int
	_ = json.NewDecoder(resp.Body).Decode(&userCount)
	resp.Body.Close()
	if userCount != 0 {
		t.Fatalf("initial user-count = %d, want 0", userCount)
	}

	// 2. Unauthenticated get-session returns null
	resp, err = http.Get(env.server.URL + "/api/auth/get-session")
	if err != nil {
		t.Fatalf("get-session unauth: %v", err)
	}
	rawSess, _ := io.ReadAll(resp.Body)
	resp.Body.Close()
	if strings.TrimSpace(string(rawSess)) != "null" {
		t.Fatalf("unauth get-session = %q, want null", string(rawSess))
	}

	// 3. First signup becomes owner
	code, ownerBody, ownerCookie := env.doJSON(http.MethodPost, "/api/auth/sign-up/email", "", map[string]any{
		"name":     "Owner One",
		"email":    "owner@example.invalid",
		"password": "owner-password-123",
	})
	if code != http.StatusOK {
		t.Fatalf("owner signup = %d, body=%v", code, ownerBody)
	}
	ownerUser := ownerBody["user"].(map[string]any)
	ownerID := ownerUser["id"].(string)
	if ownerUser["role"] != "owner" {
		t.Fatalf("owner role = %v, want owner", ownerUser["role"])
	}
	if ownerCookie == "" {
		t.Fatalf("expected session cookie on signup")
	}

	// 4. get-session returns owner session & user
	code, sessBody, _ := env.doJSON(http.MethodGet, "/api/auth/get-session", ownerCookie, nil)
	if code != http.StatusOK || sessBody["user"].(map[string]any)["id"] != ownerID {
		t.Fatalf("get-session = %d %v", code, sessBody)
	}

	// 5. Close registration in global_settings -> self-signup blocked with 401
	if _, err := env.opened.DB.ExecContext(ctx, `
		INSERT INTO global_settings (user_id, settings, updated_at)
		VALUES ('00000000-0000-0000-0000-000000000000', '{"allowRegistration":false}', 1700000000)
	`); err != nil {
		t.Fatalf("insert global_settings: %v", err)
	}
	code, closedBody, _ := env.doJSON(http.MethodPost, "/api/auth/sign-up/email", "", map[string]any{
		"name":     "Blocked User",
		"email":    "blocked@example.invalid",
		"password": "password-123456",
	})
	if code != http.StatusUnauthorized {
		t.Fatalf("closed signup = %d %v, want 401", code, closedBody)
	}

	// 6. Admin can still create user when registration is closed
	code, createdBody, _ := env.doJSON(http.MethodPost, "/api/auth/admin/create-user", ownerCookie, map[string]any{
		"name":     "Reader User",
		"email":    "reader@example.invalid",
		"password": "reader-password-123",
		"role":     "user",
	})
	if code != http.StatusOK {
		t.Fatalf("admin create-user = %d %v", code, createdBody)
	}
	readerID := createdBody["user"].(map[string]any)["id"].(string)

	// 7. Reader signs in, regular user cannot access admin endpoints (403)
	code, _, readerCookie := env.doJSON(http.MethodPost, "/api/auth/sign-in/email", "", map[string]any{
		"email":    "reader@example.invalid",
		"password": "reader-password-123",
	})
	if code != http.StatusOK || readerCookie == "" {
		t.Fatalf("reader sign-in = %d, cookie=%q", code, readerCookie)
	}
	code, _, _ = env.doJSON(http.MethodGet, "/api/auth/admin/list-users", readerCookie, nil)
	if code != http.StatusForbidden {
		t.Fatalf("non-admin list-users = %d, want 403", code)
	}

	// 8. update-user, change-email, change-password
	code, _, _ = env.doJSON(http.MethodPost, "/api/auth/update-user", readerCookie, map[string]any{
		"name": "Reader Updated",
	})
	if code != http.StatusOK {
		t.Fatalf("update-user = %d", code)
	}
	code, _, _ = env.doJSON(http.MethodPost, "/api/auth/change-email", readerCookie, map[string]any{
		"newEmail": "reader2@example.invalid",
	})
	if code != http.StatusOK {
		t.Fatalf("change-email = %d", code)
	}
	code, _, rotatedCookie := env.doJSON(http.MethodPost, "/api/auth/change-password", readerCookie, map[string]any{
		"currentPassword":     "reader-password-123",
		"newPassword":         "reader-new-password-456",
		"revokeOtherSessions": true,
	})
	if code != http.StatusOK || rotatedCookie == "" {
		t.Fatalf("change-password = %d, cookie=%q", code, rotatedCookie)
	}
	// Old session cookie should now be invalid.
	respOld, _ := http.NewRequest(http.MethodGet, env.server.URL+"/api/auth/get-session", nil)
	respOld.Header.Set("Cookie", readerCookie)
	oldRes, _ := http.DefaultClient.Do(respOld)
	oldBody, _ := io.ReadAll(oldRes.Body)
	oldRes.Body.Close()
	if strings.TrimSpace(string(oldBody)) != "null" {
		t.Fatalf("revoked session should return null, got %q", string(oldBody))
	}
	readerCookie = rotatedCookie

	// 9. Admin promotes reader to admin, then admin tries to modify/delete owner -> all 403!
	code, _, _ = env.doJSON(http.MethodPost, "/api/auth/admin/set-role", ownerCookie, map[string]any{
		"userId": readerID,
		"role":   "admin",
	})
	if code != http.StatusOK {
		t.Fatalf("set-role admin = %d", code)
	}
	for _, tc := range []struct {
		path string
		body map[string]any
	}{
		{"/api/auth/admin/remove-user", map[string]any{"userId": ownerID}},
		{"/api/auth/admin/set-role", map[string]any{"userId": ownerID, "role": "user"}},
		{"/api/auth/admin/update-user", map[string]any{"userId": ownerID, "data": map[string]any{"role": "user"}}},
		{"/api/auth/admin/ban-user", map[string]any{"userId": ownerID}},
	} {
		code, errBody, _ := env.doJSON(http.MethodPost, tc.path, readerCookie, tc.body)
		if code != http.StatusForbidden {
			t.Fatalf("%s on owner = %d %v, want 403", tc.path, code, errBody)
		}
	}

	// 10. Admin list-users, update-user, set-user-password, ban/unban
	code, listBody, _ := env.doJSON(http.MethodGet, "/api/auth/admin/list-users?limit=10", ownerCookie, nil)
	if code != http.StatusOK || int(listBody["total"].(float64)) != 2 {
		t.Fatalf("list-users = %d %v", code, listBody)
	}
	code, updBody, _ := env.doJSON(http.MethodPost, "/api/auth/admin/update-user", ownerCookie, map[string]any{
		"userId": readerID,
		"data":   map[string]any{"name": "Admin Edited", "role": "user"},
	})
	if code != http.StatusOK || updBody["name"] != "Admin Edited" || updBody["role"] != "user" {
		t.Fatalf("admin update-user = %d %v", code, updBody)
	}
	code, _, _ = env.doJSON(http.MethodPost, "/api/auth/admin/set-user-password", ownerCookie, map[string]any{
		"userId":      readerID,
		"newPassword": "admin-reset-password",
	})
	if code != http.StatusOK {
		t.Fatalf("admin set-user-password = %d", code)
	}
	code, _, _ = env.doJSON(http.MethodPost, "/api/auth/admin/ban-user", ownerCookie, map[string]any{
		"userId":    readerID,
		"banReason": "Testing ban",
	})
	if code != http.StatusOK {
		t.Fatalf("admin ban-user = %d", code)
	}
	code, _, _ = env.doJSON(http.MethodPost, "/api/auth/sign-in/email", "", map[string]any{
		"email":    "reader2@example.invalid",
		"password": "admin-reset-password",
	})
	if code != http.StatusForbidden {
		t.Fatalf("banned user sign-in = %d, want 403", code)
	}
	code, _, _ = env.doJSON(http.MethodPost, "/api/auth/admin/unban-user", ownerCookie, map[string]any{
		"userId": readerID,
	})
	if code != http.StatusOK {
		t.Fatalf("admin unban-user = %d", code)
	}
	code, _, readerCookie2 := env.doJSON(http.MethodPost, "/api/auth/sign-in/email", "", map[string]any{
		"email":    "reader2@example.invalid",
		"password": "admin-reset-password",
	})
	if code != http.StatusOK || readerCookie2 == "" {
		t.Fatalf("unbanned user sign-in = %d", code)
	}

	// 11. Sign-out invalidates session
	code, _, _ = env.doJSON(http.MethodPost, "/api/auth/sign-out", readerCookie2, map[string]any{})
	if code != http.StatusOK {
		t.Fatalf("sign-out = %d", code)
	}

	// 12. Removing user who owns a collection returns 400 (matching server/utils/auth.ts)
	if _, err := env.opened.DB.ExecContext(ctx, `
		INSERT INTO collections (id, name, owner_user_id, is_personal, is_default, created_at, updated_at)
		VALUES ('col-owned-by-reader', 'Owned', ?, 0, 0, 1700000000, 1700000000)
	`, readerID); err != nil {
		t.Fatalf("create collection owned by reader: %v", err)
	}
	code, _, _ = env.doJSON(http.MethodPost, "/api/auth/admin/remove-user", ownerCookie, map[string]any{
		"userId": readerID,
	})
	if code != http.StatusBadRequest {
		t.Fatalf("remove-user with owned collection = %d, want 400", code)
	}
	if _, err := env.opened.DB.ExecContext(ctx, `DELETE FROM collections WHERE id = 'col-owned-by-reader'`); err != nil {
		t.Fatalf("delete owned collection: %v", err)
	}
	code, _, _ = env.doJSON(http.MethodPost, "/api/auth/admin/remove-user", ownerCookie, map[string]any{
		"userId": readerID,
	})
	if code != http.StatusOK {
		t.Fatalf("remove-user after deleting collection = %d, want 200", code)
	}

	// 13. Pending collection migration blocks auth mutations (503) while keeping get-session/sign-in/sign-out working.
	if _, err := env.opened.DB.ExecContext(ctx, `UPDATE system_state SET value = 'pending' WHERE key = 'collections-model'`); err != nil {
		t.Fatalf("set pending: %v", err)
	}
	code, _, _ = env.doJSON(http.MethodGet, "/api/auth/get-session", ownerCookie, nil)
	if code != http.StatusOK {
		t.Fatalf("get-session during pending migration = %d, want 200", code)
	}
	code, _, _ = env.doJSON(http.MethodPost, "/api/auth/update-user", ownerCookie, map[string]any{"name": "Blocked"})
	if code != http.StatusServiceUnavailable {
		t.Fatalf("update-user during pending migration = %d, want 503", code)
	}
}

func TestAuthRateLimiting(t *testing.T) {
	ctx := context.Background()
	dbPath := filepath.Join(t.TempDir(), "ratelimit.db")
	opened, err := db.Open(ctx, "file:"+dbPath)
	if err != nil {
		t.Fatalf("db.Open: %v", err)
	}
	t.Cleanup(func() { _ = opened.DB.Close() })
	if _, err := db.Migrate(ctx, opened.DB, opened.FilePath, opened.IsMemory, delb.MigrationsFS); err != nil {
		t.Fatalf("db.Migrate: %v", err)
	}

	mux := http.NewServeMux()
	svc := auth.NewService(auth.ServiceOptions{
		DB:     opened.DB,
		Secret: "ratelimit-secret-0123456789abcdef0123456789",
		Logger: slog.New(slog.NewTextHandler(io.Discard, nil)),
		RateLimit: auth.RateLimitConfig{
			Window:      10 * 1e9,
			MaxRequests: 2,
		},
	})
	svc.RegisterRoutes(mux)
	srv := httptest.NewServer(mux)
	t.Cleanup(srv.Close)

	post := func(path string, body map[string]any) *http.Response {
		b, _ := json.Marshal(body)
		req, _ := http.NewRequest(http.MethodPost, srv.URL+path, bytes.NewReader(b))
		req.Header.Set("Origin", srv.URL)
		req.Header.Set("Content-Type", "application/json")
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			t.Fatalf("POST %s: %v", path, err)
		}
		return resp
	}

	// First 2 sign-in attempts hit normal handler (401 invalid credentials), 3rd returns 429 with X-Retry-After.
	for i := 0; i < 2; i++ {
		resp := post("/api/auth/sign-in/email", map[string]any{
			"email":    "nobody@example.invalid",
			"password": "wrong-password",
		})
		resp.Body.Close()
		if resp.StatusCode != http.StatusUnauthorized {
			t.Fatalf("attempt %d status = %d, want 401", i+1, resp.StatusCode)
		}
	}
	resp := post("/api/auth/sign-in/email", map[string]any{
		"email":    "nobody@example.invalid",
		"password": "wrong-password",
	})
	resp.Body.Close()
	if resp.StatusCode != http.StatusTooManyRequests {
		t.Fatalf("3rd sign-in status = %d, want 429", resp.StatusCode)
	}
	retryAfter := resp.Header.Get("X-Retry-After")
	if retryAfter == "" {
		t.Fatalf("expected X-Retry-After header on 429 response")
	}

	// Sign-up bucket is independent from sign-in bucket: 2 succeed, 3rd returns 429.
	for i := 0; i < 2; i++ {
		r := post("/api/auth/sign-up/email", map[string]any{
			"name":     "User",
			"email":    "rl-" + string(rune('a'+i)) + "@example.invalid",
			"password": "password-123456",
		})
		r.Body.Close()
		if r.StatusCode != http.StatusOK {
			t.Fatalf("signup %d status = %d, want 200", i+1, r.StatusCode)
		}
	}
	r3 := post("/api/auth/sign-up/email", map[string]any{
		"name":     "User",
		"email":    "rl-c@example.invalid",
		"password": "password-123456",
	})
	r3.Body.Close()
	if r3.StatusCode != http.StatusTooManyRequests || r3.Header.Get("X-Retry-After") == "" {
		t.Fatalf("3rd signup = (%d, X-Retry-After=%q), want 429 with header", r3.StatusCode, r3.Header.Get("X-Retry-After"))
	}
}
